func formatUserStatus(isVerified bool) string {
	if isVerified {
		return "Verified"
	}
	return "Unverified"
}

func getStatusColor(isVerified bool) string {
	if isVerified {
		return "success"
	}
	return "warning"
}

func formatUserRole(isAdmin bool) string {
	if isAdmin {
		return "Admin"
	}
	return "User"
}

func getRoleColor(isAdmin bool) string {
	if isAdmin {
		return "primary"
	}
	return "secondary"
}

func getToggleAdminLabel(isAdmin bool) string {
	if isAdmin {
		return "Remove Admin"
	}
	return "Make Admin"
}

func getToggleAdminColor(isAdmin bool) string {
	if isAdmin {
		return "warning"
	}
	return "success"
}

func getToggleAdminIcon(isAdmin bool) string {
	if isAdmin {
		return "👤"
	}
	return "👑"
}

func formatDate(t time.Time) string {
	if t.IsZero() {
		return "-"
	}
	return t.Format("Jan 2, 2006")
}

